"Les étapes, les récits et les photos du voyage. Ajoute tes propres souvenirs avec leurs photos.":"यात्रा के पड़ाव, कहानियाँ और फ़ोटो। अपनी फ़ोटो के साथ अपनी यादें जोड़ो।",
"📤 Tout renvoyer (voyage + photos)":"📤 सब फिर से भेजें (यात्रा + फ़ोटो)",
"🔑 Nouveau code (repartir à neuf)":"🔑 नया कोड (नए सिरे से)",
"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"“{0}” के लिए नया कोड बनाना है?\n\nयात्रा, उसकी एंट्री और फ़ोटो इस नए कोड के तहत फिर से सर्वर पर जाएँगी। फिर दूसरे फ़ोन को नए कोड से जुड़ना होगा (मेरी यात्राएँ → शेयर की गई यात्रा में जुड़ें)।",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ यात्रा नए कोड के तहत नहीं भेजी जा सकी: {0}\nकनेक्शन अच्छा होने पर “सब फिर से भेजें” से दोबारा कोशिश करो।",
"✅ Voyage en ligne : le code peut être donné":"✅ यात्रा ऑनलाइन है: कोड दिया जा सकता है",
"Ce voyage avait déjà un code (effacé du serveur, par exemple) ? Colle-le ici pour le réutiliser : les autres téléphones le retrouveront.\nSinon laisse vide : un nouveau code sera créé.":"क्या इस यात्रा का पहले से कोई कोड था (जैसे सर्वर से मिटाया गया)? फिर से इस्तेमाल करने के लिए उसे यहाँ पेस्ट करो: दूसरे फ़ोन उसे फिर पा लेंगे।\nवरना खाली छोड़ो: नया कोड बनेगा।",
"🗑 Supprimé du serveur : {0} fiche(s) et {1} photo(s).\nTes données restent sur ce téléphone.\n\nGarder le code sur ce téléphone ?\nOK = je garde le code : tu pourras tout renvoyer plus tard avec le même code (bouton « Tout renvoyer »).\nAnnuler = j’oublie ce code ici.":"🗑 सर्वर से हटाया गया: {0} एंट्री और {1} फ़ोटो।\nतुम्हारा डेटा इसी फ़ोन पर रहेगा।\n\nइस फ़ोन पर कोड रखना है?\nOK = कोड रखो: बाद में उसी कोड से सब फिर से भेज सकोगे (“सब फिर से भेजें” बटन)।\nरद्द करें = यहाँ यह कोड भूल जाओ।",
"Le code est gardé. Pour tout remettre sur le serveur : {0} → « Tout renvoyer ».":"कोड रखा गया है। सब कुछ फिर से सर्वर पर डालने के लिए: {0} → “सब फिर से भेजें”।",
"Mes voyages → le voyage → code":"मेरी यात्राएँ → यात्रा → कोड",
"📤 Voyage ou photos non arrivés ?":"📤 यात्रा या फ़ोटो नहीं पहुँचीं?",
"Renvoie vers le serveur toutes les fiches et toutes les photos de ce téléphone, par exemple après une suppression sur le serveur. Rien n’est dupliqué.":"इस फ़ोन की सारी एंट्री और सारी फ़ोटो फिर से सर्वर पर भेजता है, जैसे सर्वर से डेटा हटाने के बाद। कुछ भी दोहराया नहीं जाता।",
"📤 Tout renvoyer":"📤 सब फिर से भेजें",
"{0} fiche(s) et {1} photo(s) remises en file d’envoi.":"{0} एंट्री और {1} फ़ोटो फिर से भेजने की कतार में।",
