"👀 3 voyages de démo sont prêts (rien n’est partagé) :\n\n📍 En cours : on est au jour 7 — traceur, steps, tickets, courses, plafond, parts inégales.\n🧳 Préparation : le même Japon dans 6 mois, à organiser.\n🗺️ Passés / 🏁 Bilan : le voyage terminé avec ses photos, son album et ses comptes.\n\nPasse d’un onglet à l’autre en haut de l’écran. « Supprimer la démo » efface tout.":"👀 3 डेमो यात्राएँ तैयार हैं (कुछ भी शेयर नहीं होता):\n\n📍 चल रही: हम दिन 7 पर हैं — ट्रैकर, क़दम, रसीदें, किराना, दैनिक सीमा, असमान हिस्से।\n🧳 तैयारी: वही जापान यात्रा 6 महीने बाद, व्यवस्थित करनी है।\n🗺️ पिछली / 🏁 सारांश: फ़ोटो, एल्बम और हिसाब के साथ पूरी हुई यात्रा।\n\nस्क्रीन के ऊपर टैब बदलो। “डेमो हटाएँ” सब मिटा देता है।",
"Supprimer le voyage de démo ?\n\nTes propres voyages ne sont pas touchés.":"डेमो यात्रा हटानी है?\n\nतुम्हारी अपनी यात्राओं को कुछ नहीं होगा।",
