"Tout est enregistré sur ce téléphone ({0} Ko){1}. L’export reste ta copie de secours, et il contient aussi l’archive 2026.":"सब कुछ इसी फ़ोन पर सहेजा है ({0} KB){1}। एक्सपोर्ट तुम्हारी बैकअप कॉपी बना रहता है, और उसमें 2026 का आर्काइव भी है।",
