"Le carnet partagé contient déjà {0} fiches.\n\nOK = utiliser le carnet partagé (recommandé pour rejoindre : ce téléphone garde seulement ses profils).\nAnnuler = fusionner les deux carnets.":"साझा डायरी में पहले से {0} एंट्री हैं।\n\nOK = साझा डायरी इस्तेमाल करें (जुड़ने के लिए सुझाया गया: यह फ़ोन सिर्फ़ अपनी प्रोफ़ाइल रखता है)।\nरद्द करें = दोनों डायरियाँ मिलाएँ।",
