"Rejoins notre carnet de voyage 🧳\n{0}\nCode du carnet : {1}\n(⚙️ Partage → colle le code → Activer la synchro)":"हमारी यात्रा डायरी में जुड़ो 🧳\n{0}\nडायरी कोड: {1}\n(⚙️ शेयरिंग → कोड पेस्ट करो → सिंक चालू करें)",
