"Ce carnet n’est pas synchronisé : rien n’est stocké sur le serveur.":"यह डायरी सिंक नहीं है: सर्वर पर कुछ भी नहीं रखा गया।",
"Demander l’effacement de ce carnet sur le serveur ?\n\nToutes ses données en ligne seront supprimées, pour TOUS ses membres. Un e-mail va être préparé : il contient seulement l’identifiant chiffré du carnet, jamais son code.":"सर्वर से इस डायरी को मिटाने का अनुरोध करना है?\n\nइसका सारा ऑनलाइन डेटा सभी सदस्यों के लिए मिटा दिया जाएगा। एक ईमेल तैयार होगा: उसमें सिर्फ़ डायरी की एन्क्रिप्टेड आईडी होगी, कभी उसका कोड नहीं।",
"Les données restent sur le serveur partagé, tu pourras le rejoindre à nouveau avec le code.":"डेटा साझा सर्वर पर रहता है, तुम कोड से फिर जुड़ सकते हो।",
