"🗑 Cartes effacées":"🗑 नक्शे मिटा दिए गए",
"Chargement de la carte…":"नक्शा लोड हो रहा है…",
"Carte hors ligne":"ऑफ़लाइन नक्शा",
"Pas de réseau : télécharge les cartes avant le départ (Outils).":"नेटवर्क नहीं: निकलने से पहले नक्शे डाउनलोड करो (टूल्स)।",
