"Accessible en fauteuil roulant":"व्हीलचेयर के लिए सुलभ",
"Accès en fauteuil limité":"व्हीलचेयर के लिए सीमित पहुँच",
"Entrée gratuite":"प्रवेश मुफ़्त",
"Pas d’horaires ni de description trouvés pour ce lieu.":"इस जगह के लिए न समय मिला, न विवरण।",
